// ShareFile .
// @router /share/file/ [POST]
func ShareFile(ctx context.Context, c *app.RequestContext) {
	// 1. 解析表单参数
	expireValueStr := c.DefaultPostForm("expire_value", "1")
	expireStyle := c.DefaultPostForm("expire_style", "day")
	requireAuth := c.DefaultPostForm("require_auth", "false") == "true"
	password := c.DefaultPostForm("password", "")

	expireValue, err := strconv.Atoi(expireValueStr)
	if err != nil {
		expireValue = 1
	}

	// 过期样式白名单
	if err := utils.CheckExpireStyleAllowed(expireStyle); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}

	// 2. 获取上传文件
	file, err := c.FormFile("file")
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请上传文件",
		})
		return
	}

	// 3. 检查文件大小（upload.upload_size 单请求体上限，0=不限；
	// 修复：此前硬编码 10MB 不读配置，调大 upload_size 对直传通道无效）
	if maxSize := utils.GetMaxUploadSize(); maxSize > 0 && file.Size > maxSize {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    errcode.CodeTooLarge,
			"message": fmt.Sprintf("文件大小超过限制（最大 %d MB）", maxSize/1024/1024),
		})
		return
	}

	// 3.5 上传闸门 + 匿名配额（治理回归：此前在 SaveFile 落盘之后才校验，
	// 被拒请求已把整文件写入存储——local 留孤儿、远端后端永久泄漏）
	{
		var gateUserID *uint
		if v, ok := middleware.UserIDFromContext(ctx); ok {
			gateUserID = &v
		}
		if err := gate.CheckUploadAllowed(gateUserID); err != nil {
			resp.NewTypedError(c, err)
			return
		}
		if err := gate.CheckUploadLogin(gateUserID); err != nil {
			resp.NewTypedError(c, err)
			return
		}
		if gateUserID == nil {
			if err := gate.CheckAnonymousQuota(ctx, middleware.ClientIP(c), file.Size); err != nil {
				resp.NewTypedError(c, err)
				return
			}
		}
	}

	// 4. 生成唯一文件名（原始文件名消毒后仅作展示存储，磁盘名用 UUID）
	originalFilename := utils.SanitizeFileName(file.Filename)

	// 4.5 内容安全校验：黑名单 + 白名单优先 + 魔数（修复：直传分享此前完全绕过
	// 扩展名检查，与 chunk/presign 通道防护不一致；魔数拦截"改扩展名"伪装）
	// E2E 密文分享跳过魔数复检（密文头是随机字节，必然不过魔数表）
	encryptedEarly := c.DefaultPostForm("encrypted", "false") == "true"
	var head []byte
	if !encryptedEarly {
		if f, err := file.Open(); err == nil {
			buf := make([]byte, 512)
			n, rerr := io.ReadFull(f, buf)
			if rerr == nil || rerr == io.ErrUnexpectedEOF {
				head = buf[:n]
			}
			_ = f.Close()
		}
		if err := utils.CheckUploadContent(originalFilename, head); err != nil {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeFileTypeDenied,
				"message": err.Error(),
			})
			return
		}
	}

	// 5+6. 落盘（磁盘布局与存储操作收口 app/share，HTTP 适配层不直连 storage）
	filePath, fileSize, fileHash, err := getShareService().SaveUploadFile(ctx, file, originalFilename)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": fmt.Sprintf("文件保存失败: %v", err),
		})
		return
	}

	// 7. 计算过期时间
	expireTime := utils.CalculateExpireTime(expireValue, expireStyle)
	expireCount := utils.CalculateExpireCount(expireStyle, expireValue)

	// 8. 获取用户ID（如果有）
	var userID *uint
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			userID = &uidUint
		}
	}

	// 9. 获取客户端 IP（可信代理解析）
	ownerIP := middleware.ClientIP(c)

	// 10. 确定上传类型
	uploadType := "anonymous"
	if userID != nil {
		uploadType = "authenticated"
	}

	// 10.5 密码保护:require_auth 时密码必填,bcrypt 哈希后入库(修复:此前 password
	// 被读取后直接丢弃,导致 PasswordHash 落库为空,取件侧空哈希校验形同虚设)
	passwordHash := ""
	if requireAuth {
		if password == "" {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    400,
				"message": "开启密码保护时必须提供密码",
			})
			return
		}
		hash, err := utils.HashPassword(password)
		if err != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    500,
				"message": "密码处理失败",
			})
			return
		}
		passwordHash = hash
	}

	// 自定义取件码（P3）：仅登录用户可指定（防匿名抢注）
	customCode := ""
	if userID != nil {
		customCode = c.DefaultPostForm("custom_code", "")
	}

	// 11. 构建分享请求（encrypted 于 4.5 处解析；E2E 密文分享）
	shareReq := &shareService.ShareFileReq{
		Channel:      "direct",
		FilePath:     filePath,
		Size:         fileSize,
		Text:         originalFilename, // 存储原始文件名
		ExpiredAt:    expireTime,
		ExpiredCount: expireCount,
		RequireAuth:  requireAuth,
		PasswordHash: passwordHash,
		UserID:       userID,
		UploadType:   uploadType,
		OwnerIP:      ownerIP,
		FileHash:     fileHash,
		Encrypted:    encryptedEarly,
		CustomCode:   customCode,
	}

	// 12. 调用 service 创建分享记录
	shareResult, err := getShareService().ShareFile(ctx, shareReq)
	if err != nil {
		resp.NewTypedError(c, err) // 配额/审核等 typed error 按业务码透传
		return
	}

	// 13. 构建响应（base_url 取配置值；此前硬编码 localhost:12345，
	// 反代/容器部署下 API 返回的分享链接不可直接用，前端仅靠自行改写兜底）
	var cfgRef *conf.ServerConfig
	if cfg := conf.GetGlobalConfig(); cfg != nil {
		cfgRef = &cfg.Server
	}
	fullShareURL := fmt.Sprintf("%s/share/%s", cfgRef.PublicBaseURL(defaultBaseURL), shareResult.Code)

	// 传输日志（上传，异步）
	transfer.Record(transfer.Entry{
		Operation: transfer.OpUpload, FileCodeID: shareResult.ID, Code: shareResult.Code,
		FileName: originalFilename, FileSize: shareResult.Size,
		UserID: userID, APIKeyID: apiKeyIDPtr(ctx),
		Username: middleware.UsernameFromContext(ctx), IP: ownerIP,
	})

	resp := &sharemodel.ShareFileResp{
		Code:    200,
		Message: "文件上传成功",
		Data: &sharemodel.ShareData{
			Code: shareResult.Code,
			URL:  fullShareURL,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// GetUserShares 获取用户的分享列表
// @router /share/user [GET]
func GetUserShares(ctx context.Context, c *app.RequestContext) {
	// 获取用户ID（需要登录）
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    401,
			"message": "请先登录",
		})
		return
	}

	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "用户ID格式错误",
		})
		return
	}

	// 获取分页参数
	page := 1
	pageSize := 10
	if p := c.Query("page"); p != "" {
		_, _ = fmt.Sscanf(p, "%d", &page)
	}
	if ps := c.Query("page_size"); ps != "" {
		_, _ = fmt.Sscanf(ps, "%d", &pageSize)
	}

	// 调用 service
	files, total, err := getShareService().GetFilesByUserID(ctx, userID, page, pageSize)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": err.Error(),
		})
		return
	}

	// 转换为响应格式
	items := make([]map[string]interface{}, len(files))
	for i, f := range files {
		items[i] = map[string]interface{}{
			"code":           f.Code,
			"filename":       f.UUIDFileName,
			"file_size":      f.Size,
			"content_type":   f.UploadType,
			"download_count": f.UsedCount,
			"created_at":     f.CreatedAt.Format("2006-01-02 15:04:05"),
		}
		if f.ExpiredAt != nil {
			items[i]["expire_time"] = f.ExpiredAt.Format("2006-01-02 15:04:05")
		}
	}

	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "获取成功",
		"data": map[string]interface{}{
			"items":     items,
			"total":     total,
			"page":      page,
			"page_size": pageSize,
		},
	})
}

// DeleteShare 删除分享
// @router /share/:code [DELETE]
func DeleteShare(ctx context.Context, c *app.RequestContext) {
	// 获取用户ID（需要登录）
	userIDVal, exists := c.Get("user_id")
	if !exists {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    401,
			"message": "请先登录",
		})
		return
	}

	userID, ok := userIDVal.(uint)
	if !ok {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "用户ID格式错误",
		})
		return
	}

	code := c.Param("code")
	if code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请提供分享码",
		})
		return
	}

	// 调用 service 删除分享
	err := getShareService().DeleteFileByCode(ctx, code, userID)
	if err != nil {
		// 根据错误类型返回不同的状态码
		errMsg := err.Error()
		if errMsg == "分享不存在" {
			c.JSON(consts.StatusNotFound, map[string]interface{}{
				"code":    404,
				"message": errMsg,
			})
			return
		}
		if errMsg == "无权限删除此分享" {
			c.JSON(consts.StatusForbidden, map[string]interface{}{
				"code":    403,
				"message": errMsg,
			})
			return
		}

		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": fmt.Sprintf("删除失败: %s", errMsg),
		})
		return
	}

	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "删除成功",
	})
}

// GetShare .
// @router /share/select/ [GET]
func GetShare(ctx context.Context, c *app.RequestContext) {
	code := c.Query("code")
	password := c.Query("password")

	if code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请提供分享码",
		})
		return
	}

	// 下载闸门：download.require_login（服务端 enforce，此前只透传前端）
	var pickupUserID *uint
	if v, ok := middleware.UserIDFromContext(ctx); ok {
		pickupUserID = &v
	}
	if err := gate.CheckDownloadLogin(pickupUserID); err != nil {
		resp.NewTypedError(c, err)
		return
	}

	// 失败锁定检查（防取件码/密码爆破）
	lock := middleware.GetDefaultLockout()
	lockKey := middleware.FormatLockKey("pickup", middleware.ClientIP(c), code)
	if remain, locked := lock.CheckLocked(ctx, lockKey); locked {
		c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
			"code":    errcode.CodeTooManyAttempts,
			"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", remain),
		})
		return
	}

	// 获取分享内容
	fileCode, err := getShareService().GetFileByCode(ctx, code)
	if err != nil {
		var blocked *shareService.ShareBlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": "分享不存在或已过期",
		})
		return
	}

	// 密码保护校验(修复:此处响应包含分享正文,空密码提示后必须真正校验密码,
	// 此前 TODO 未实现导致任意非空密码均可取到内容)
	if fileCode.RequireAuth {
		if password == "" {
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    401,
				"message": "需要密码",
				"data": map[string]interface{}{
					"has_password": true,
				},
			})
			return
		}
		if fileCode.PasswordHash == "" || !utils.CheckPassword(fileCode.PasswordHash, password) {
			// 记录失败（达到阈值触发锁定）
			_, _ = lock.RecordFailure(ctx, lockKey)
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeSharePasswordWrong,
				"message": "密码错误",
			})
			return
		}
	}
	// 校验通过，清空失败计数
	lock.Reset(ctx, lockKey)

	// 下发下载令牌（security.download_token.enabled 时 /share/download 必须携带）
	downloadURL := fmt.Sprintf("/share/download?code=%s", fileCode.Code)
	if tk := security.GenerateDownloadToken(fileCode.Code); tk != "" {
		downloadURL += "&token=" + tk
	}

	// 构建响应（保持 {code,message,data:{...}} 结构与前端兼容；
	// data 内附加 download_url/token，ShareDetail thrift 模型无此字段）
	data := map[string]interface{}{
		"code":         fileCode.Code,
		"text":         fileCode.Text,
		"file_name":    fileCode.UUIDFileName,
		"file_size":    fmt.Sprintf("%d", fileCode.Size),
		"url":          downloadURL, // 修复：原 /download/:code 无对应路由，落到 SPA fallback
		"download_url": downloadURL,
		"has_password": fileCode.RequireAuth,
		"encrypted":    fileCode.Encrypted, // E2E：前端需以链接 #fragment 中的密钥解密
	}
	if tk := security.GenerateDownloadToken(fileCode.Code); tk != "" {
		data["token"] = tk
	}
	if fileCode.ExpiredAt != nil {
		data["expire_time"] = fileCode.ExpiredAt.Format("2006-01-02 15:04:05")
	}

	// 多文件列表（P0 多文件）：非文本分享附带 files 数组（含单文件，前端统一渲染）；
	// is_multi 标记文件数 >1（前端显示"打包下载"）。查询失败静默省略（不阻断取件）。
	if !shareService.IsTextShare(fileCode) {
		if items, lerr := getShareService().ListShareFiles(ctx, code); lerr == nil && len(items) > 0 {
			files := make([]map[string]interface{}, 0, len(items))
			for _, it := range items {
				files = append(files, map[string]interface{}{
					"id":   it.ID,
					"name": it.Name,
					"size": it.Size,
				})
			}
			data["files"] = files
			data["is_multi"] = len(items) > 1
		}
	}

	c.JSON(consts.StatusOK, map[string]interface{}{
		"code":    200,
		"message": "获取成功",
		"data":    data,
	})
}

// downloadTokenEnabled 是否强制下载令牌（security.download_token.enabled，默认 true）
func downloadTokenEnabled() bool {
	cfg := conf.GetGlobalConfig()
	if cfg == nil {
		return true
	}
	return cfg.Security.DownloadToken.Enabled
}

// s3DirectDownloadEnabled 是否开启 s3 直下（download.s3_direct_download，默认关）
func s3DirectDownloadEnabled() bool {
	cfg := conf.GetGlobalConfig()
	return cfg != nil && cfg.Download.S3DirectDownload
}

// authorizeAndCharge 下载链路公共鉴权段（DownloadFile / ZipDownload 共用）：
// 下载闸门 → 防爆破锁定 → 下载令牌校验 → 密码校验（GetFileWithUsage）→
// 原子扣减剩余次数。失败时已写入错误响应并返回 (nil, false)；
// 成功返回分享记录（已扣次数，调用方无须再扣）。
func authorizeAndCharge(ctx context.Context, c *app.RequestContext, code, password, token string) (*model.FileCode, bool) {
	// 下载闸门：download.require_login（服务端 enforce）
	var dlUserID *uint
	if v, ok := middleware.UserIDFromContext(ctx); ok {
		dlUserID = &v
	}
	if err := gate.CheckDownloadLogin(dlUserID); err != nil {
		resp.NewTypedError(c, err)
		return nil, false
	}

	// 失败锁定检查（防密码爆破）
	lock := middleware.GetDefaultLockout()
	lockKey := middleware.FormatLockKey("download", middleware.ClientIP(c), code)
	if remain, locked := lock.CheckLocked(ctx, lockKey); locked {
		c.JSON(consts.StatusTooManyRequests, map[string]interface{}{
			"code":    errcode.CodeTooManyAttempts,
			"message": fmt.Sprintf("尝试过于频繁，已临时锁定，请 %d 秒后重试", remain),
		})
		return nil, false
	}

	// 下载令牌校验（security.download_token.enabled，默认开）：
	// 取件查询/匿名取件接口下发时间窗 HMAC 令牌，恒时比较校验。
	// 密码通道仅对"密码保护分享"开放（2026-10-05 审计 P2 修复：此前 password
	// 参数非空即跳过"缺令牌"拦截，无密码分享加任意 &password=x 即绕过强制
	// 令牌，防盗链语义失效）；令牌由密码校验通过后的取件查询签发，等价已认证。
	tokenEnabled := downloadTokenEnabled()
	tokenValid := tokenEnabled && token != "" && security.VerifyDownloadToken(code, token)
	if tokenEnabled && !tokenValid {
		passwordOK := false
		if password != "" {
			if fc, gerr := getShareService().GetFileByCode(ctx, code); gerr == nil && fc.RequireAuth {
				passwordOK = true
			}
		}
		if !passwordOK {
			msg := "缺少下载令牌，请重新获取取件信息"
			if token != "" {
				msg = "下载令牌无效或已过期，请重新获取取件信息"
			}
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeDownloadToken,
				"message": msg,
			})
			return nil, false
		}
	}

	// 获取分享内容并校验密码（viewer IP 由 handler 注入，可信代理解析）
	viewerIP := middleware.ClientIP(c)
	fileCode, err := getShareService().GetFileWithUsage(ctx, code, password, viewerIP, tokenValid)
	if err != nil {
		var blocked *shareService.ShareBlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return nil, false
		}
		if err.Error() == "密码错误" {
			_, _ = lock.RecordFailure(ctx, lockKey)
			c.JSON(consts.StatusUnauthorized, map[string]interface{}{
				"code":    errcode.CodeSharePasswordWrong,
				"message": "密码错误",
				"data": map[string]interface{}{
					"has_password": true,
				},
			})
			return nil, false
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": "分享不存在或已过期",
		})
		return nil, false
	}
	lock.Reset(ctx, lockKey)

	// 原子扣减下载次数（DB 为准）
	if ok, uerr := getShareService().UpdateFileUsage(ctx, code); uerr != nil {
		// 记录错误但不阻止下载
		fmt.Printf("更新下载次数失败: %v\n", uerr)
	} else if !ok {
		// 次数已耗尽（并发场景下可能在 GetFileWithUsage 之后耗尽）
		c.JSON(consts.StatusForbidden, map[string]interface{}{
			"code":    403,
			"message": "取件次数已用完",
		})
		return nil, false
	}
	return fileCode, true
}

// DownloadFile 下载分享文件
// @router /share/download [GET]
func DownloadFile(ctx context.Context, c *app.RequestContext) {
	code := c.Query("code")
	password := c.Query("password")
	token := c.Query("token")

	if code == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请提供分享码",
		})
		return
	}

	fileCode, ok := authorizeAndCharge(ctx, c, code, password, token)
	if !ok {
		return
	}
	viewerIP := middleware.ClientIP(c)

	// 如果是文本分享，直接返回文本（IsTextShare = Text 非空且无文件路径；
	// 文件分享的原始文件名也存在 Text 字段，不能仅凭 Text 判定——回归 P0）
	if shareService.IsTextShare(fileCode) {
		c.Header("Content-Type", "text/plain; charset=utf-8")
		c.Header("Content-Disposition", `inline; filename="text.txt"`)
		c.SetBodyString(fileCode.Text)
		return
	}

	// 多文件分享下载入口（P0 多文件）：
	//   ?file=<子文件ID> → 单文件流；未指定且文件数 >1 → 直接流式 zip 打包
	var fileID uint
	if raw := c.Query("file"); raw != "" {
		if v, perr := strconv.ParseUint(raw, 10, 64); perr == nil {
			fileID = uint(v)
		}
	}
	if fileID > 0 {
		if streamChildFile(ctx, c, code, fileID, viewerIP) {
			return
		}
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": "文件不存在或不属于该分享",
		})
		return
	}
	if items, lerr := getShareService().ListShareFiles(ctx, code); lerr == nil && len(items) > 1 {
		// 多文件：跳转 zip 端点（鉴权段已在上文完成并扣减次数，zip 端点用
		// 免重复扣减的内部直通：此处直接流式打包，不再 302，避免浏览器二次请求
		// 丢失鉴权参数）。zip 组装失败回退错误响应。
		if streamShareZip(ctx, c, fileCode, viewerIP) {
			return
		}
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "打包下载失败",
		})
		return
	}

	// 如果是文件分享，流式返回文件
	filePath := fileCode.GetFilePath()
	if filePath == "" {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "文件路径为空",
		})
		return
	}

	// 传输日志（异步，fire-and-forget）：此前 transfer_log 表无任何写入方，
	// 传输日志页与趋势下载序列一直空数据。文本分享按查看计，文件按下载计。
	logTransfer := func() {
		logName := fileCode.UUIDFileName
		if logName == "" {
			logName = fileCode.Text // 直传分享未落 UUIDFileName，Text 存的是原始文件名
		}
		if shareService.IsTextShare(fileCode) {
			logName = "text.txt"
		}
		var logUser *uint
		logUsername := ""
		if uid, ok := middleware.UserIDFromContext(ctx); ok {
			logUser = &uid
		}
		if n := middleware.UsernameFromContext(ctx); n != "" {
			logUsername = n
		}
		transfer.Record(transfer.Entry{
			Operation: transfer.OpDownload, FileCodeID: fileCode.ID, Code: code,
			FileName: logName, FileSize: fileCode.Size,
			UserID: logUser, APIKeyID: apiKeyIDPtr(ctx),
			Username: logUsername, IP: viewerIP,
		})
	}

	// s3 直下（可选开关 download.s3_direct_download，默认关）：当前后端支持
	// 真预签名时 302 到短时效预签名 GET，下载流量不经过服务器。
	// 访问校验/密码/次数扣减均已在上方完成；不支持或签发失败则回退服务端中转。
	if s3DirectDownloadEnabled() {
		if u, perr := getShareService().PresignDownloadURL(ctx, filePath, 10*time.Minute); perr == nil {
			logTransfer()
			c.Header("Cache-Control", "no-store")
			c.Redirect(consts.StatusFound, []byte(u))
			return
		}
	}

	// 获取文件读取器
	fileName := fileCode.UUIDFileName
	if fileName == "" {
		// 向后兼容：如果UUIDFileName为空，则使用Prefix + Suffix
		fileName = fileCode.Prefix + fileCode.Suffix
	}

	// 本地后端：直接 c.File（原生 Range/断点续传/MIME 推断；P3 下载断点续传）。
	// 远端后端无本地路径，回退下方流式中转（S3 直下开关可用时流量不经服务器）。
	payload, err := getShareService().OpenShareDownload(ctx, filePath)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": fmt.Sprintf("获取文件失败: %v", err),
		})
		return
	}
	if payload.LocalAbs != "" {
		logTransfer()
		c.Header("Content-Type", "application/octet-stream")
		c.Header("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, fileName))
		c.File(payload.LocalAbs)
		return
	}

	logTransfer()
	c.Header("Content-Type", "application/octet-stream")
	c.Header("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, fileName))
	c.Header("Content-Length", fmt.Sprintf("%d", payload.Size))

	// 流式传输文件内容。
	// 回归要点（P0）：Hertz 的 SetBodyStream 在 handler 返回后才真正写出 body，
	// 因此绝不能 defer reader.Close()——读到的是已关闭 reader（0 字节空文件），
	// 文件下载分支曾因此长期不可用。改为读到 EOF 即自动关闭。
	c.SetBodyStream(newCloseOnEOFReader(payload.ReadCloser), int(payload.Size))
}

// closeOnEOFReader 包装 ReadCloser：读至 EOF 时自动 Close。
// 用于 Hertz 延迟流式写出的场景（handler 返回后才开始读 body）。
type closeOnEOFReader struct {
	rc io.ReadCloser
}

func (w *closeOnEOFReader) Read(p []byte) (int, error) {
	n, err := w.rc.Read(p)
	if err == io.EOF {
		_ = w.rc.Close()
	}
	return n, err
}

func newCloseOnEOFReader(rc io.ReadCloser) io.Reader {
	return &closeOnEOFReader{rc: rc}
}

// apiKeyIDPtr 提取 ctx 中的 API Key 归因（JWT/匿名请求返回 nil）。
func apiKeyIDPtr(ctx context.Context) *uint {
	if id, ok := middleware.APIKeyIDFromContext(ctx); ok {
		return &id
	}
	return nil
}
